const pick = (names) => { for (const n of names) { try { const j = $(n).first().json; if (j) return j; } catch (e) {} } return {}; };

// §19 WF08 — วางแผนอิสรภาพทางการเงินรายเดือน (ใช้ตัวเลขจริงที่มีในระบบ + สมมติฐานที่ตั้งได้)
const members = pick(['การเงิน: สมาชิก']);
const leads = pick(['การเงิน: ผู้สนใจ']);
const done = pick(['การเงิน: งานที่ปิดแล้ว']);
const sd = $getWorkflowStaticData('global');
// สมมติฐาน (แก้ได้ใน workflow: static data key 'assumptions')
const A = Object.assign({
  avgPremium: 24000,        // เบี้ยเฉลี่ยต่อกรมธรรม์ (บาท/ปี)
  commissionRate: 0.25,     // อัตราค่าตอบแทนรวมปีแรก
  conversionRate: 0.12,     // อัตราปิดการขายจากผู้สนใจ
  activeRate: 0.35,         // สัดส่วนสมาชิกที่ active จริง
  incomePerActiveMember: 3500,  // รายได้ทีมต่อสมาชิก active ต่อเดือน (บาท)
  expenseRatio: 0.35,       // ค่าใช้จ่ายทีม/ดำเนินงาน
  reinvestRatio: 0.30,      // เก็บ Reinvest
  welfareRatio: 0.10,       // สวัสดิการทีม
  monthlyTarget: 100000,    // เป้าหมายอิสรภาพทางการเงินต่อเดือน (บาท)
}, sd.assumptions || {});
const leadsTotal = Number(leads.total || 0);
const membersTotal = Number(members.total || 0);
const membersActive = Number(members.active || 0) || Math.round(membersTotal * A.activeRate);
const tasksClosed = Number(done.total || (done.tasks || []).length || 0);
const deals = Math.round(leadsTotal * A.conversionRate);
const directIncome = Math.round(deals * A.avgPremium * A.commissionRate / 12);
const teamIncome = Math.round(membersActive * A.incomePerActiveMember);
const passiveIncome = directIncome + teamIncome;
const expense = Math.round(passiveIncome * A.expenseRatio);
const netProfit = passiveIncome - expense;
const reinvest = Math.round(netProfit * A.reinvestRatio);
const welfare = Math.round(netProfit * A.welfareRatio);
const freedomRatio = Math.round((passiveIncome / A.monthlyTarget) * 1000) / 10;
const month = new Date().toISOString().slice(0, 7);
const snap = { month, passiveIncome, directIncome, teamIncome, expense, netProfit, reinvest, welfare,
  freedomRatio, leadsTotal, membersTotal, membersActive, deals, tasksClosed, at: new Date().toISOString() };
sd.monthly = Array.isArray(sd.monthly) ? sd.monthly.filter(m => m.month !== month) : [];
sd.monthly.push(snap);
if (sd.monthly.length > 36) sd.monthly = sd.monthly.slice(-36);
const prev = sd.monthly.length > 1 ? sd.monthly[sd.monthly.length - 2] : null;
return [{ json: { snap, assumptions: A, prev, gap: Math.max(0, A.monthlyTarget - passiveIncome),
  nextTarget: Math.round(passiveIncome * 1.2), history: sd.monthly.slice(-6),
  summary: 'เดือน ' + month + ': รายได้เชิงรับประมาณ ' + passiveIncome.toLocaleString('th-TH') + ' บาท'
    + ' (ตัวแทนเอง ' + directIncome.toLocaleString('th-TH') + ' + ทีม ' + teamIncome.toLocaleString('th-TH') + ')'
    + ' · กำไรสุทธิ ' + netProfit.toLocaleString('th-TH') + ' บาท · คิดเป็น ' + freedomRatio + '% ของเป้าหมาย '
    + A.monthlyTarget.toLocaleString('th-TH') + ' บาท' } }];

